1	import java.util.Collections;
2	import java.util.LinkedList;
3	import java.util.List;
4	import java.util.Random;
5	
6	/**
7	 * Represent a rectangular grid of field positions.
8	 * Each position is able to store a single actor.
9	 *
10	 * @version 18.02.22 (DD:MM:YY)
11	 */
12	public class Field
13	{
14	    // A random number generator for providing random locations:
15	    private static final Random rand = Randomizer.getRandom();
16	    // The depth and width of the field:
17	    private int depth, width;
18	    // Storage for the actors:
19	    private Object[][] field;
20	    
21	    /**
22	     * Represent a field of the given dimensions.
23	     * 
24	     * @param depth The depth of the field.
25	     * @param width The width of the field.
26	     */
27	    public Field(int depth, int width)
28	    {
29	        this.depth = depth;
30	        this.width = width;
31	        
32	        field = new Object[depth][width];
33	    }
34	    
35	    /**
36	     * Empty the field.
37	     */
38	    public void clear()
39	    {
40	        for (int row = 0; row < depth; row++)
41	        {
42	            for (int col = 0; col < width; col++)
43	            {
44	                field[row][col] = null;
45	            }
46	        }
47	    }
48	    
49	    /**
50	     * Clear the given location.
51	     * 
52	     * @param location The location to clear.
53	     */
54	    public void clear(Location location)
55	    {
56	        field[location.getRow()][location.getCol()] = null;
57	    }
58	    
59	    /**
60	     * Place an actor at the given location.
61	     * If there is already an actor at the location it will
62	     * be lost.
63	     * @param actor The actor to be placed.
64	     * @param location Where to place the actor.
65	     */
66	    public void place(Object actor, Location location)
67	    {
68	        field[location.getRow()][location.getCol()] = actor;
69	    }
70	    
71	    /**
72	     * Return the actor at the given location, if any.
73	     * 
74	     * @param location Where in the field.
75	     * @return The actor at the given location, or null if there is none.
76	     */
77	    public Object getObjectAt(Location location)
78	    {
79	        return getObjectAt(location.getRow(), location.getCol());
80	    }
81	    
82	    /**
83	     * Return the actor at the given location, if any.
84	     * 
85	     * @param row The desired row.
86	     * @param col The desired column.
87	     * @return The actor at the given location, or null if there is none.
88	     */
89	    public Object getObjectAt(int row, int col)
90	    {
91	        return field[row][col];
92	    }
93	    
94	    /**
95	     * Get a shuffled list of the free adjacent locations.
96	     * 
97	     * @param searchLocation Get locations adjacent to this.
98	     * @return A list of free adjacent locations.
99	     */
100	    public List<Location> getFreeAdjacentLocations(Location searchLocation)
101	    {
102	        // The list of free locations to be returned:
103	        List<Location> free = new LinkedList<>();
104	        
105	        List<Location> adjacentLocations = adjacentLocations(searchLocation);
106	        
107	        for (Location location : adjacentLocations)
108	            if (getObjectAt(location) == null) free.add(location);
109	        
110	        return free;
111	    }
112	    
113	    /**
114	     * Try to find a free location that is adjacent to the
115	     * given location. If there is none, return null.
116	     * The returned location will be within the valid bounds
